import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";

import { useStudio, type ToolActivity } from "../../state/StudioContext";
import type { ChatMessage } from "../../types";
import { UiActionContext } from "../../ui/actions";
import { RichText } from "../../ui/RichText";
import { UiRenderer } from "../../ui/UiRenderer";

const QUICK_PROMPTS: { label: string; prompt: string }[] = [
  {
    label: "Define a job",
    prompt: "Help me define a new Job-to-be-Done for developer platforms.",
  },
  {
    label: "Simulate a bet",
    prompt: "Simulate the impact of an Auto-Sync Agent on outcome O-1.",
  },
  { label: "ODI guidelines", prompt: "Give me the ODI Stage-by-Stage guidelines." },
];

const PHASE_LABEL: Record<string, string> = {
  health_check: "Reaching the model",
  mcp_tools: "Loading your tools",
  model: "Thinking",
};

function Thinking({ phase }: { phase: string | null }) {
  const label = (phase && PHASE_LABEL[phase]) || "Thinking";
  return (
    <div className="chat-thinking" role="status">
      <span className="chat-thinking__dot" />
      <span className="chat-thinking__dot" />
      <span className="chat-thinking__dot" />
      <span className="chat-thinking__label">{label}…</span>
    </div>
  );
}

function ToolRail({ activity }: { activity: ToolActivity[] }) {
  return (
    <div className="chat-activity" aria-label="Tool activity">
      {activity.map((tool, index) => (
        <span
          className={`chat-activity__chip chat-activity__chip--${tool.status}`}
          key={`${tool.name}-${index}`}
          title={tool.preview}
        >
          {tool.name}
          <span aria-hidden="true" className="chat-activity__mark">
            {tool.status === "ok" ? "✓" : tool.status === "error" ? "!" : "…"}
          </span>
        </span>
      ))}
    </div>
  );
}

function Turn({ message }: { message: ChatMessage }) {
  const parts: ReactNode[] = message.parts.length
    ? message.parts.map((part, index) =>
        part.kind === "text" ? (
          <div className="chat-turn__text" key={`text-${index}`}>
            <RichText text={part.text} />
          </div>
        ) : (
          <UiRenderer key={part.id} node={part.node} />
        ),
      )
    : [];

  return (
    <article className={`chat-turn chat-turn--${message.role}`}>
      {parts.length ? parts : <div className="chat-turn__text">{message.content}</div>}
    </article>
  );
}

export function ChatCopilot() {
  const {
    messages,
    streaming,
    thinkingPhase,
    toolActivity,
    sendMessage,
    engagementLevel,
    setEngagementLevel,
  } = useStudio();
  const [draft, setDraft] = useState("");
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const logRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function onKeyDown(event: KeyboardEvent) {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
        event.preventDefault();
        inputRef.current?.focus();
      }
    }
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, []);

  useEffect(() => {
    logRef.current?.scrollTo({ top: logRef.current.scrollHeight, behavior: "smooth" });
  }, [messages, toolActivity, streaming]);

  useEffect(() => {
    if (messages.length > 1 && engagementLevel === 0) {
      setEngagementLevel(1);
    }
  }, [messages.length, engagementLevel, setEngagementLevel]);

  const dispatcher = useMemo(
    () => ({
      onIntent: (intent: string) => {
        void sendMessage(intent);
      },
      busy: streaming,
    }),
    [sendMessage, streaming],
  );

  async function submit(event: React.FormEvent) {
    event.preventDefault();
    const text = draft;
    setDraft("");
    await sendMessage(text);
  }

  const lastMessage = messages[messages.length - 1];
  const awaitingReply =
    streaming && lastMessage?.role === "assistant" && lastMessage.parts.length === 0;

  return (
    <section className="chat-copilot">
      <header className="chat-copilot__head">
        <h2 className="chat-copilot__title">Copilot</h2>
        <p className="caption chat-copilot__caption">
          Speak your intent. The studio answers with evidence.
        </p>
      </header>

      <div className="chat-quick-pills">
        {QUICK_PROMPTS.map((quick) => (
          <button
            key={quick.label}
            type="button"
            className="chat-quick-pill"
            disabled={streaming}
            onClick={() => void sendMessage(quick.prompt)}
          >
            {quick.label}
          </button>
        ))}
      </div>

      <UiActionContext.Provider value={dispatcher}>
        <div
          className="chat-log"
          ref={logRef}
          role="log"
          aria-live="polite"
          aria-busy={streaming}
          aria-label="Chat with the studio copilot"
        >
          {messages.map((message, index) => (
            <Turn
              key={`${message.role}-${index}`}
              message={message}
            />
          ))}

          {streaming && toolActivity.length > 0 ? (
            <ToolRail activity={toolActivity} />
          ) : null}
          {awaitingReply ? <Thinking phase={thinkingPhase} /> : null}
        </div>
      </UiActionContext.Provider>

      <form className="chat-input-row" onSubmit={submit}>
        <textarea
          ref={inputRef}
          className="studio-input"
          rows={2}
          aria-label="State your product intent or question"
          placeholder="Ask, or tell me what your customers struggle with…"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === "Enter" && !event.shiftKey) {
              event.preventDefault();
              void submit(event);
            }
          }}
        />
        <button type="submit" className="studio-button" disabled={streaming || !draft.trim()}>
          Send
        </button>
      </form>
    </section>
  );
}

/* eslint-disable react-refresh/only-export-components -- context module intentionally exports the hook and constants alongside the provider */
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";

import {
  addOutcome as apiAddOutcome,
  addStep as apiAddStep,
  fetchCanvas,
  fetchConfig,
  healthLlm,
  healthMcp,
  streamChat,
} from "../api/studioApi";
import type { RawSseEvent } from "../api/sse";
import type {
  AddOutcomePayload,
  AddStepPayload,
  CanvasData,
  ChatMessage,
  ChatPart,
  StudioConfig,
} from "../types";
import { catalogManifest } from "../ui/catalog";
import { parseUiSpec, type UiNode } from "../ui/protocol";

const SETTINGS_KEY = "studio.settings";
const CANVAS_KEY = "studio.canvas";
const ENGAGEMENT_KEY = "studio.engagementLevel";

const CATALOG_MANIFEST = catalogManifest();

export const WELCOME_MESSAGE =
  "Welcome to **The Living Studio**.\n\n" +
  "This is a living map of human progress. Tell me what your customers are struggling with — " +
  "I will answer with the evidence, not a ticket.";

const WELCOME_CARD: UiNode = {
  type: "stack",
  props: {
    gap: "sm",
    actions: [
      {
        label: "Define a job",
        intent: "Help me define a Job-to-be-Done.",
        tone: "primary",
      },
      {
        label: "Show the ODI guidelines",
        intent: "Give me the ODI stage-by-stage guidelines.",
      },
    ],
  },
  children: [],
};

export function welcomeMessage(): ChatMessage {
  return {
    role: "assistant",
    content: WELCOME_MESSAGE,
    parts: [
      { kind: "text", text: WELCOME_MESSAGE },
      { kind: "ui", id: "welcome", node: WELCOME_CARD },
    ],
  };
}

export const EMPTY_CONFIG: StudioConfig = {
  base_url: "http://localhost:8001/v1",
  api_key: "local",
  model_name: "local-tools-model",
  mcp_url: "http://localhost:8000/mcp",
};

export type ToastKind = "success" | "error" | "info";

export interface Toast {
  id: number;
  kind: ToastKind;
  message: string;
}

export interface ToolActivity {
  name: string;
  status: string;
  preview?: string;
}

export interface ConnectionReport {
  sidecarReachable: boolean;
  mcpReachable: boolean;
  llmHealthy: boolean;
}

export interface StudioContextValue {
  settings: StudioConfig;
  saveSettings: (config: StudioConfig) => void;
  engagementLevel: number;
  setEngagementLevel: (level: number) => void;
  canvas: CanvasData | null;
  canvasLoading: boolean;
  canvasCached: boolean;
  refreshCanvas: () => Promise<void>;
  llmHealth: { healthy: boolean | null; message: string };
  mcpReachable: boolean | null;
  sidecarReachable: boolean | null;
  /** Probe the sidecar, MCP server, and model. Optionally against unsaved config. */
  checkConnections: (override?: Partial<StudioConfig>) => Promise<ConnectionReport>;
  messages: ChatMessage[];
  streaming: boolean;
  thinkingPhase: string | null;
  toolActivity: ToolActivity[];
  sendMessage: (text: string) => Promise<void>;
  clearChat: () => void;
  addStep: (payload: Omit<AddStepPayload, "mcp_url">) => Promise<void>;
  addOutcome: (payload: Omit<AddOutcomePayload, "mcp_url">) => Promise<void>;
  pendingSimOutcome: string | null;
  requestSimulate: (outcomeId: string) => void;
  clearPendingSimOutcome: () => void;
  activeTab: string;
  setActiveTab: (tab: string) => void;
  toasts: Toast[];
  pushToast: (kind: ToastKind, message: string) => void;
  dismissToast: (id: number) => void;
}

const StudioContext = createContext<StudioContextValue | null>(null);

function loadSettings(): StudioConfig {
  try {
    const raw = localStorage.getItem(SETTINGS_KEY);
    if (raw) {
      return { ...EMPTY_CONFIG, ...(JSON.parse(raw) as Partial<StudioConfig>) };
    }
  } catch {
    /* ignore malformed cache */
  }
  return EMPTY_CONFIG;
}

function loadCanvasCache(): CanvasData | null {
  try {
    const raw = localStorage.getItem(CANVAS_KEY);
    if (raw) {
      return JSON.parse(raw) as CanvasData;
    }
  } catch {
    /* ignore malformed cache */
  }
  return null;
}

function loadEngagementLevel(): number {
  try {
    const raw = localStorage.getItem(ENGAGEMENT_KEY);
    if (raw) {
      return Math.max(0, Math.min(2, parseInt(raw, 10)));
    }
  } catch {
    /* ignore malformed cache */
  }
  return 0;
}

export function StudioProvider({ children }: { children: ReactNode }) {
  const [settings, setSettings] = useState<StudioConfig>(loadSettings);
  const [canvas, setCanvas] = useState<CanvasData | null>(loadCanvasCache);
  const [canvasLoading, setCanvasLoading] = useState(false);
  const [canvasCached, setCanvasCached] = useState(() => loadCanvasCache() !== null);
  const [engagementLevel, setEngagementLevel] = useState(() => loadEngagementLevel());
  const [llmHealth, setLlmHealth] = useState<{ healthy: boolean | null; message: string }>({
    healthy: null,
    message: "Health not checked yet.",
  });
  const [mcpReachable, setMcpReachable] = useState<boolean | null>(null);
  const [sidecarReachable, setSidecarReachable] = useState<boolean | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>(() => [welcomeMessage()]);
  const [streaming, setStreaming] = useState(false);
  const [thinkingPhase, setThinkingPhase] = useState<string | null>(null);
  const [toolActivity, setToolActivity] = useState<ToolActivity[]>([]);
  const [pendingSimOutcome, setPendingSimOutcome] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState("landscape");
  const [toasts, setToasts] = useState<Toast[]>([]);
  const toastId = useRef(0);
  const abortRef = useRef<AbortController | null>(null);

  const pushToast = useCallback((kind: ToastKind, message: string) => {
    const id = (toastId.current += 1);
    setToasts((prev) => [...prev, { id, kind, message }]);
    window.setTimeout(() => {
      setToasts((prev) => prev.filter((toast) => toast.id !== id));
    }, 6000);
  }, []);

  const dismissToast = useCallback((id: number) => {
    setToasts((prev) => prev.filter((toast) => toast.id !== id));
  }, []);

  const saveSettings = useCallback((config: StudioConfig) => {
    setSettings(config);
    try {
      localStorage.setItem(SETTINGS_KEY, JSON.stringify(config));
    } catch {
      /* storage unavailable */
    }
  }, []);

  const saveEngagementLevel = useCallback((level: number) => {
    setEngagementLevel(level);
    try {
      localStorage.setItem(ENGAGEMENT_KEY, String(level));
    } catch {
      /* storage unavailable */
    }
  }, []);

  const checkConnections = useCallback(
    async (override: Partial<StudioConfig> = {}): Promise<ConnectionReport> => {
      const target = { ...settings, ...override };
      const [sidecar, mcp, llm] = await Promise.all([
        fetchConfig()
          .then(() => true)
          .catch(() => false),
        healthMcp(target.mcp_url)
          .then((result) => result.reachable)
          .catch(() => false),
        healthLlm({
          base_url: target.base_url,
          api_key: target.api_key,
          model: target.model_name,
        }).catch((error: unknown) => ({
          healthy: false,
          message: (error as Error).message || "The model did not answer.",
        })),
      ]);

      setSidecarReachable(sidecar);
      setMcpReachable(mcp);
      setLlmHealth(llm);
      return { sidecarReachable: sidecar, mcpReachable: mcp, llmHealthy: llm.healthy };
    },
    [settings],
  );

  const refreshCanvas = useCallback(async () => {
    setCanvasLoading(true);
    try {
      const data = await fetchCanvas(settings.mcp_url);
      setCanvas(data);
      setCanvasCached(false);
      try {
        localStorage.setItem(CANVAS_KEY, JSON.stringify(data));
      } catch {
        /* storage unavailable */
      }
    } catch (error) {
      pushToast("error", `Canvas sync failed: ${(error as Error).message}`);
    } finally {
      setCanvasLoading(false);
    }
  }, [settings.mcp_url, pushToast]);

  const addStep = useCallback(
    async (payload: Omit<AddStepPayload, "mcp_url">) => {
      try {
        await apiAddStep({ ...payload, mcp_url: settings.mcp_url });
        pushToast("success", "Step added to Job Map!");
        await refreshCanvas();
      } catch (error) {
        pushToast("error", `Error adding step: ${(error as Error).message}`);
      }
    },
    [settings.mcp_url, pushToast, refreshCanvas],
  );

  const addOutcome = useCallback(
    async (payload: Omit<AddOutcomePayload, "mcp_url">) => {
      try {
        await apiAddOutcome({ ...payload, mcp_url: settings.mcp_url });
        pushToast("success", "Outcome captured successfully!");
        await refreshCanvas();
      } catch (error) {
        pushToast("error", `Error capturing outcome: ${(error as Error).message}`);
      }
    },
    [settings.mcp_url, pushToast, refreshCanvas],
  );

  const clearPendingSimOutcome = useCallback(() => setPendingSimOutcome(null), []);

  const requestSimulate = useCallback((outcomeId: string) => {
    setPendingSimOutcome(outcomeId);
    setActiveTab("impact");
  }, []);

  const sendMessage = useCallback(
    async (text: string) => {
      const trimmed = text.trim();
      if (!trimmed || streaming) {
        return;
      }

      const history: ChatMessage[] = [
        ...messages,
        { role: "user", content: trimmed, parts: [{ kind: "text", text: trimmed }] },
      ];
      setMessages([...history, { role: "assistant", content: "", parts: [] }]);
      setStreaming(true);
      setThinkingPhase("health_check");
      setToolActivity([]);

      const controller = new AbortController();
      abortRef.current = controller;

      let content = "";
      let parts: ChatPart[] = [];
      let uiCount = 0;

      const publish = () => {
        const snapshot: ChatMessage = { role: "assistant", content, parts: [...parts] };
        setMessages((prev) => {
          if (prev.length === 0) {
            return prev;
          }
          const next = [...prev];
          next[next.length - 1] = snapshot;
          return next;
        });
      };

      const appendText = (chunk: string) => {
        if (!chunk) {
          return;
        }
        content += chunk;
        const last = parts[parts.length - 1];
        parts =
          last?.kind === "text"
            ? [...parts.slice(0, -1), { kind: "text", text: last.text + chunk }]
            : [...parts, { kind: "text", text: chunk }];
        publish();
      };

      const appendSurface = (spec: unknown) => {
        const parsed = parseUiSpec(spec, CATALOG_MANIFEST);
        if (!parsed.ok) {
          // The sidecar validates before emitting; this is the last line of defence.
          console.warn(`Dropped an invalid UI surface: ${parsed.reason}`);
          return;
        }
        uiCount += 1;
        parts = [...parts, { kind: "ui", id: `ui-${uiCount}`, node: parsed.node }];
        publish();
      };

      const handleEvent = (event: RawSseEvent) => {
        switch (event.event) {
          case "status":
            setThinkingPhase(String(event.data.phase ?? ""));
            break;
          case "delta":
            appendText(String(event.data.text ?? ""));
            break;
          case "ui":
            appendSurface(event.data.spec);
            break;
          case "tool":
            setToolActivity((prev) => [
              ...prev,
              {
                name: String(event.data.name ?? ""),
                status: String(event.data.status ?? ""),
                preview: event.data.preview ? String(event.data.preview) : undefined,
              },
            ]);
            break;
          case "message": {
            const finalText = String(event.data.content ?? content);
            const hasSurface = parts.some((part) => part.kind === "ui");
            if (!hasSurface) {
              content = finalText;
              parts = content ? [{ kind: "text", text: content }] : [];
              publish();
            } else {
              content = finalText;
            }
            break;
          }
          case "canvas_dirty":
            void refreshCanvas();
            break;
          case "error":
            pushToast("error", String(event.data.message ?? "Unknown chat error"));
            break;
          default:
            break;
        }
      };

      try {
        await streamChat(
          {
            base_url: settings.base_url,
            api_key: settings.api_key,
            model: settings.model_name,
            mcp_url: settings.mcp_url,
            messages: history.map((message) => ({ role: message.role, content: message.content })),
            ui_catalog: CATALOG_MANIFEST,
          },
          handleEvent,
          controller.signal,
        );
      } catch (error) {
        if ((error as Error).name !== "AbortError") {
          pushToast("error", `Error during assistant completion: ${(error as Error).message}`);
          setMessages((prev) => {
            const next = [...prev];
            if (next.length && next[next.length - 1].content === "") {
              next.pop();
            }
            return next;
          });
        }
      } finally {
        setStreaming(false);
        setThinkingPhase(null);
        abortRef.current = null;
      }
    },
    [messages, streaming, settings, refreshCanvas, pushToast],
  );

  const clearChat = useCallback(() => {
    abortRef.current?.abort();
    setMessages([welcomeMessage()]);
    setToolActivity([]);
    setStreaming(false);
    setThinkingPhase(null);
  }, []);

  // Initial hydration: env defaults, canvas, health probes.
  useEffect(() => {
    let cancelled = false;

    async function boot() {
      try {
        const defaults = await fetchConfig();
        if (!cancelled) {
          setSidecarReachable(true);
          if (localStorage.getItem(SETTINGS_KEY) === null) {
            saveSettings(defaults);
          }
        }
      } catch {
        if (!cancelled) {
          setSidecarReachable(false);
        }
      }
      if (cancelled) {
        return;
      }
      void refreshCanvas();
      void healthMcp(settings.mcp_url)
        .then((result) => {
          if (!cancelled) {
            setMcpReachable(result.reachable);
          }
        })
        .catch(() => undefined);
      void healthLlm({
        base_url: settings.base_url,
        api_key: settings.api_key,
        model: settings.model_name,
      })
        .then((result) => {
          if (!cancelled) {
            setLlmHealth(result);
          }
        })
        .catch(() => undefined);
    }

    void boot();
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const value = useMemo<StudioContextValue>(
    () => ({
      settings,
      saveSettings,
      engagementLevel,
      setEngagementLevel: saveEngagementLevel,
      canvas,
      canvasLoading,
      canvasCached,
      refreshCanvas,
      llmHealth,
      mcpReachable,
      sidecarReachable,
      checkConnections,
      messages,
      streaming,
      thinkingPhase,
      toolActivity,
      sendMessage,
      clearChat,
      addStep,
      addOutcome,
      pendingSimOutcome,
      requestSimulate,
      clearPendingSimOutcome,
      activeTab,
      setActiveTab,
      toasts,
      pushToast,
      dismissToast,
    }),
    [
      settings,
      saveSettings,
      canvas,
      canvasLoading,
      canvasCached,
      refreshCanvas,
      llmHealth,
      mcpReachable,
      sidecarReachable,
      checkConnections,
      messages,
      streaming,
      thinkingPhase,
      toolActivity,
      sendMessage,
      clearChat,
      addStep,
      addOutcome,
      pendingSimOutcome,
      requestSimulate,
      clearPendingSimOutcome,
      activeTab,
      engagementLevel,
      saveEngagementLevel,
      toasts,
      pushToast,
      dismissToast,
    ],
  );

  return <StudioContext.Provider value={value}>{children}</StudioContext.Provider>;
}

export function useStudio(): StudioContextValue {
  const context = useContext(StudioContext);
  if (!context) {
    throw new Error("useStudio must be used within a StudioProvider");
  }
  return context;
}

