import { fireEvent, render, screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";

import type { ChatMessage } from "../../types";
import { catalogManifest } from "../../ui/catalog";
import { parseUiSpec, type UiNode } from "../../ui/protocol";
import { ChatCopilot } from "./ChatCopilot";

const { sendMessage, MESSAGES } = vi.hoisted(() => ({
  sendMessage: vi.fn(async () => undefined),
  MESSAGES: [] as unknown[],
}));

vi.mock("../../state/StudioContext", () => ({
  useStudio: () => ({
    messages: MESSAGES,
    streaming: false,
    thinkingPhase: null,
    toolActivity: [],
    sendMessage,
    engagementLevel: 2,
    setEngagementLevel: () => undefined,
  }),
}));

const OUTCOME_SPEC = {
  type: "outcome-card",
  props: {
    id: "O-1",
    statement: "Minimize the time it takes to propagate secrets",
    importance: 9,
    satisfaction: 3,
    actions: [{ label: "Simulate this bet", intent: "Simulate a bet on O-1", tone: "primary" }],
  },
};

function nodeOf(spec: unknown): UiNode {
  const result = parseUiSpec(spec, catalogManifest());
  if (!result.ok) {
    throw new Error(result.reason);
  }
  return result.node;
}

function seed(messages: ChatMessage[]) {
  MESSAGES.length = 0;
  MESSAGES.push(...messages);
}

describe("ChatCopilot transcript", () => {
  it("interleaves prose and surfaces in the order the agent produced them", () => {
    seed([
      {
        role: "assistant",
        content: "Here is the outcome.\nThen build it.",
        parts: [
          { kind: "text", text: "Here is the **outcome**." },
          { kind: "ui", id: "ui-1", node: nodeOf(OUTCOME_SPEC) },
          { kind: "text", text: "Then build it." },
        ],
      },
    ]);

    const { container } = render(<ChatCopilot />);

    const prose = screen.getByText("Then build it.");
    const card = screen.getByLabelText("Outcome O-1");
    const bold = container.querySelector("strong");

    expect(bold).toHaveTextContent("outcome");
    // The card sits between the two paragraphs, not appended after both.
    expect(bold?.compareDocumentPosition(card)).toBe(Node.DOCUMENT_POSITION_FOLLOWING);
    expect(card.compareDocumentPosition(prose)).toBe(Node.DOCUMENT_POSITION_FOLLOWING);
  });

  it("routes a card action back to the agent as a prompt", () => {
    seed([
      {
        role: "assistant",
        content: "",
        parts: [{ kind: "ui", id: "ui-1", node: nodeOf(OUTCOME_SPEC) }],
      },
    ]);
    sendMessage.mockClear();

    render(<ChatCopilot />);
    fireEvent.click(screen.getByRole("button", { name: "Simulate this bet" }));

    expect(sendMessage).toHaveBeenCalledWith("Simulate a bet on O-1");
  });

  it("falls back to plain content when a message has no parts", () => {
    seed([{ role: "assistant", content: "Legacy message", parts: [] }]);
    render(<ChatCopilot />);
    expect(screen.getByText("Legacy message")).toBeInTheDocument();
  });
});

