import "@testing-library/jest-dom/vitest";

// jsdom does not implement scrolling; the transcript auto-scrolls on update.
if (typeof Element !== "undefined" && typeof Element.prototype.scrollTo !== "function") {
  Object.defineProperty(Element.prototype, "scrollTo", {
    configurable: true,
    writable: true,
    value: () => undefined,
  });
}

/**
 * Node 25 can expose an inert global `localStorage` (an empty object with no
 * methods) that shadows jsdom's implementation. Without storage the studio
 * cannot persist settings, canvas, or onboarding state, so replace it with a
 * small in-memory Storage when the environment's is unusable.
 */
function installMemoryStorage(): void {
  const values = new Map<string, string>();
  const storage: Storage = {
    get length() {
      return values.size;
    },
    clear: () => {
      values.clear();
    },
    getItem: (key: string) => (values.has(key) ? values.get(key)! : null),
    key: (index: number) => [...values.keys()][index] ?? null,
    removeItem: (key: string) => {
      values.delete(key);
    },
    setItem: (key: string, value: string) => {
      values.set(String(key), String(value));
    },
  };

  for (const target of [window, globalThis]) {
    try {
      Object.defineProperty(target, "localStorage", {
        configurable: true,
        writable: true,
        value: storage,
      });
    } catch {
      // Some environments lock the property; the module-level fallbacks still
      // let the studio run without persistence.
    }
  }
}

if (typeof window !== "undefined") {
  const current = window.localStorage as Partial<Storage> | undefined;
  if (!current || typeof current.getItem !== "function" || typeof current.clear !== "function") {
    installMemoryStorage();
  }
}

